int calculate_minimum_tour_length(int N, int M, int[] X) {
    int totalLength = 0;
    for (int i = 0; i < M - 1; i++) {
        totalLength += Math.abs(X[i + 1] - X[i]);
    }
    totalLength += Math.abs(X[M - 1] - X[0]); // Complete the circular tour

    int minTourLength = totalLength;
    for (int i = 0; i < M; i++) {
        int currentLength = totalLength;
        if (i == 0) {
            currentLength -= Math.abs(X[M - 1] - X[0]);
            currentLength += Math.abs(X[M - 1] - X[1]);
        } else if (i == M - 1) {
            currentLength -= Math.abs(X[M - 1] - X[0]);
            currentLength += Math.abs(X[M - 2] - X[0]);
        } else {
            currentLength -= Math.abs(X[i] - X[i - 1]);
            currentLength -= Math.abs(X[i + 1] - X[i]);
            currentLength += Math.abs(X[i + 1] - X[i - 1]);
        }
        minTourLength = Math.min(minTourLength, currentLength);
    }
    return minTourLength;
}
